import React from 'react';
import {renderToStaticMarkup} from 'react-dom/server';
import {buildPlan,applyPlan,uid,outstanding,ledgerBalance} from '../lib/erp-engine.ts';
import {financeSnapshot,ageing,ageBands,documentStatus,partyDocuments,cashMovements,financeParties} from '../lib/finance.ts';
import Finance,{FinancePartyForm} from '../app/erp-finance.tsx';
let state={records:[],journal:[],audit:[]},passed=0;
const check=(v,m)=>{if(!v)throw Error(m);passed++},record=id=>state.records.find(r=>r.id===id),run=input=>{const p=buildPlan({...input,requestId:uid()},state);state=applyPlan(state,p);return p.focusId},reject=(input,m)=>{let fail=false;try{buildPlan({...input,requestId:uid()},state)}catch{fail=true}check(fail,m)};
const base={action:'create',date:'2026-01-01'},line=n=>[{description:'Service',qty:1,rate:n}];
const parties={};
for(const company of ['Hagadol','WMK']){
 const client=run({...base,company,type:'crm_company',name:'Shared client name',role:'Customer',paymentTermsDays:30,billingAddress:'Client address',taxReference:'TIN example'});
 const supplier=run({...base,company,type:'crm_company',name:'Supplier '+company,role:'Supplier',paymentTermsDays:0});parties[company]={client,supplier};
 const inv=run({...base,company,type:'invoice',name:'Client invoice',partyId:client,customer:'Untrusted label',lines:line(1000),taxRate:18});
 check(record(inv).customer==='Shared client name'&&record(inv).due==='2026-01-31','Linked identity and due terms derived '+company);
 check(financeSnapshot(state,company,'2026-01-31').receivables===0,'Draft does not affect balances');run({action:'post',id:inv});
 const receipt=run({action:'pay',id:inv,amount:300,date:'2026-02-01',account:'Bank',reference:'Test receipt'});
 check(record(receipt).partyId===client&&record(receipt).customer===record(inv).customer,'Receipt inherits party');
 check(financeSnapshot(state,company,'2026-01-31').receivables===1180,'Future receipt excluded');
 check(financeSnapshot(state,company,'2026-02-01').receivables===880,'Partial payment as of date');
 const credit=run({...base,date:'2026-02-02',company,type:'credit',name:'Client credit',target:inv,lines:line(100),taxRate:18,partyId:supplier});run({action:'post',id:credit});
 check(record(credit).partyId===client&&outstanding(record(inv))===762,'Credit inherits invoice identity and reduces outstanding');
 run({action:'void',id:receipt,date:'2026-02-03',reason:'Receipt reversed'});
 check(financeSnapshot(state,company,'2026-02-01').receivables===880,'Later reversal preserves previous balance');
 check(financeSnapshot(state,company,'2026-02-03').receivables===1062,'Reversal reinstates receivable');
 run({action:'void',id:credit,date:'2026-02-04',reason:'Credit reversed'});
 check(financeSnapshot(state,company,'2026-02-04').receivables===1180,'Credit reversal reinstates balance');
 const bill=run({...base,company,type:'bill',name:'Supplier bill',partyId:supplier,lines:line(600)});run({action:'post',id:bill});check(record(bill).due==='2026-01-01','Zero days terms supported');
 run({action:'pay',id:bill,amount:600,date:'2026-02-05',account:'Bank'});
 check(financeSnapshot(state,company,'2026-02-04').payables===600&&financeSnapshot(state,company,'2026-02-05').payables===0,'Historical supplier balances');
 check(documentStatus(record(bill),'2026-02-06')==='Paid','Fully paid bill status');
 const before=ledgerBalance(state.journal.filter(j=>j.company===company));
 const expense=run({...base,company,type:'expense',name:'Paid transport',partyId:supplier,amount:50,account:'Cash'});run({action:'post',id:expense});
 check((ledgerBalance(state.journal.filter(j=>j.company===company)).Cash||0)===(before.Cash||0)-50,'Expense pays cash once');reject({action:'pay',id:expense,amount:50,date:'2026-02-05'},'Expense cannot be paid twice');
 reject({...base,company,type:'invoice',name:'Bad due',lines:line(100),due:'2025-12-31'},'Due before issue rejected');
 reject({...base,company,type:'crm_company',name:'Bad terms',paymentTermsDays:366},'Excess terms rejected');
 reject({...base,company,type:'crm_company',name:'Bad terms',paymentTermsDays:1.5},'Fractional terms rejected');
 const legacy=run({...base,company,type:'invoice',name:'Legacy typed invoice',customer:'Shared client name',lines:line(99)});run({action:'post',id:legacy});
 check(!partyDocuments(state.records,record(client),'invoice').some(r=>r.id===legacy),'Name only records not silently linked');
 const duplicate=run({...base,company,type:'crm_company',name:'Shared client name',role:'Customer'});check(partyDocuments(state.records,record(duplicate),'invoice').length===0,'Duplicate names keep separate identities');
 const oldName=record(inv).customer;run({action:'edit',id:client,fields:{name:'Renamed client'}});check(record(inv).customer===oldName,'Posted party snapshot remains immutable');
 const balance=outstanding(record(inv));run({action:'pay',id:inv,amount:balance,date:'2026-02-06'});check(documentStatus(record(inv),'2026-02-06')==='Paid','Full receipt settles invoice');reject({action:'pay',id:inv,amount:1,date:'2026-02-06'},'Overpayment rejected');
 check(financeSnapshot(state,company,'2026-01-31').receivables===1279,'Historical receivables survive later full settlement');
 check(state.journal.filter(j=>j.company===company).reduce((n,j)=>n+j.debit-j.credit,0)===0,'Company journal remains balanced');
 for(const tab of ['Overview','Customers','Suppliers','Invoices','Bills','Expenses','Payments','Ageing']){const html=renderToStaticMarkup(React.createElement(Finance,{state,company,tab,changeTab:()=>{},open:()=>{},onDetail:()=>{},payment:()=>{},act:async()=>false,busy:false,go:()=>{},onDirty:()=>{},initial:{cutoff:'2026-02-01'}}));check(!/NaN|\[object Object\]/.test(html)&&html.includes('Finance sections'),'Clean finance section '+company+'/'+tab);}
 const html=renderToStaticMarkup(React.createElement(Finance,{state,company,tab:'Customers',changeTab:()=>{},open:()=>{},onDetail:()=>{},payment:()=>{},act:async()=>false,busy:false,go:()=>{},onDirty:()=>{},initial:{profile:client,cutoff:'2026-01-31'}}));check(html.includes('Statement as at 2026-01-31')&&html.includes('1,180'),'Customer statement renders historical posted balance');
 const form=renderToStaticMarkup(React.createElement(FinancePartyForm,{company,role:'Customer',act:async()=>false,busy:false,onClose:()=>{},onDirty:()=>{}}));check(form.includes('Payment terms in days')&&form.includes('Billing address'),'Billing profile inputs');
}
reject({...base,company:'WMK',type:'invoice',name:'Cross business',partyId:parties.Hagadol.client,lines:line(10)},'Cross business customer link rejected');
reject({...base,company:'WMK',type:'invoice',name:'Unknown customer',partyId:'absent',lines:line(10)},'Missing customer reference rejected');
const cutoff='2026-04-01',dateMinus=n=>new Date(Date.parse(cutoff+'T00:00:00Z')-n*86400000).toISOString().slice(0,10);
const bandCases=[[0,'Not due'],[-1,'Not due'],[1,'1 to 30 days'],[30,'1 to 30 days'],[31,'31 to 60 days'],[60,'31 to 60 days'],[61,'61 to 90 days'],[90,'61 to 90 days'],[91,'Over 90 days'],[null,'No due date']];
for(const [days,band] of bandCases){const r={id:'boundary',company:'Hagadol',type:'invoice',status:'Posted',amount:100,paid:20,credited:10,due:days===null?'':dateMinus(days)};const result=ageing([r],'invoice',cutoff)[0];check(result.ageBand===band&&result.balance===70,'Age boundary '+days);}
check(ageBands.length===6,'Unknown due date has its own bucket');
const transfer=run({...base,company:'Hagadol',type:'transfer',name:'Internal cash transfer',amount:20,fromAccount:'Bank',toAccount:'Cash'});check(!cashMovements(state.journal,'2026-01-01','2026-02-06').some(r=>r.id.includes(transfer)),'Internal cash transfer excluded from flows');
const isolated=financeSnapshot(state,'Hagadol','2026-01-31');check(isolated.records.every(r=>r.company==='Hagadol')&&isolated.journal.every(r=>r.company==='Hagadol'),'Company isolation in finance data');
let groupState={records:[],journal:[],audit:[]};const groupRun=input=>{const p=buildPlan({...input,requestId:uid()},groupState);groupState=applyPlan(groupState,p);return p.focusId};
const internal={...base,name:'Internal service',customer:'Group company',lines:line(500),intercompany:true,intercompanyRef:'PAIR-1'};const gi=groupRun({...internal,company:'Hagadol',type:'invoice'}),gb=groupRun({...internal,company:'WMK',type:'bill'});groupRun({action:'post',id:gi});groupRun({action:'post',id:gb});
check(financeSnapshot(groupState,'Group','2026-01-31').receivables===0&&financeSnapshot(groupState,'Group','2026-01-31').payables===0,'Matched internal balances eliminated from group');
groupRun({action:'pay',id:gi,amount:200,date:'2026-02-01'});const gs=financeSnapshot(groupState,'Group','2026-02-01');check(gs.receivables===0&&gs.payables===200,'Payment timing difference retained in group');
check(ageing(gs.historical,'invoice','2026-02-01')[0].balance===300,'Ageing shows gross internal document amount');

const openingState={records:[],journal:[{id:'opening',company:'Hagadol',source:'opening',account:'Accounts receivable',debit:500,credit:0,date:'2026-01-01',description:'Opening receivables'}],audit:[]};
check(financeSnapshot(openingState,'Hagadol','2026-01-31').receivables===500,'Overview includes opening journal receivables');
check(ageing(financeSnapshot(openingState,'Hagadol','2026-01-31').historical,'invoice','2026-01-31').length===0,'Opening journals do not invent aged invoice documents');
const unclassified={id:'unclassified-fixture',company:'Hagadol',type:'crm_company',name:'Unclassified fixture',role:'Unclassified'},explicit={...unclassified,id:'explicit-customer',role:'Customer'};
check(financeParties([unclassified,explicit,{id:'cross-company',company:'WMK',type:'invoice',partyId:unclassified.id}],'Customer').map(r=>r.id).join(',')===explicit.id,'Finance directory keeps explicit roles and excludes cross company documents');
check(financeParties([unclassified,{id:'same-company',company:'Hagadol',type:'invoice',partyId:unclassified.id}],'Customer')[0]?.id===unclassified.id,'Linked customer appears without changing source role');
check(financeParties([unclassified,{id:'same-company',company:'Hagadol',type:'invoice',partyId:unclassified.id}],'Supplier').length===0,'Invoices do not classify suppliers');
check(financeParties([unclassified,{id:'same-company',company:'Hagadol',type:'bill',partyId:unclassified.id}],'Supplier')[0]?.id===unclassified.id,'Linked supplier appears from a bill');
console.log(JSON.stringify({passed,failed:0,browserTested:false,liveProductionTouched:false}));
